    "content": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://mattrace.local/schemas/material-evidence-input.json\",\n  \"title\": \"Material Evidence Extractor Input\",\n  \"type\": \"object\",\n  \"required\": [\"documents\"],\n  \"additionalProperties\": false,\n  \"properties\": {\n    \"documents\": {\n      \"type\": \"array\",\n      \"minItems\": 3,\n      \"maxItems\": 10,\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"document_id\", \"name\", \"document_type\", \"pages\"],\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"document_id\": { \"type\": \"string\", \"minLength\": 1 },\n          \"name\": { \"type\": \"string\", \"minLength\": 1 },\n          \"document_type\": { \"enum\": [\"paper\", \"patent\", \"tds\"] },\n          \"pages\": {\n            \"type\": \"array\",\n            \"minItems\": 1,\n            \"items\": {\n              \"type\": \"object\",\n              \"required\": [\"page\", \"text\"],\n              \"properties\": {\n                \"page\": { \"type\": [\"integer\", \"string\"] },\n                \"text\": { \"type\": \"string\" },\n                \"source_kind\": { \"enum\": [\"body\", \"abstract\", \"table\", \"figure_caption\", \"footnote\", \"ocr\"] }\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}\n",
    "category": "contract",
    "editable": false,
    "language": "json"
